    # rook
    for t,inter in rays(f,ORTH): gen_normal('R',f,t,inter)
    # bishop
    for t,inter in rays(f,DIAG): gen_normal('B',f,t,inter)
    # queen
    for t,inter in rays(f,ORTH+DIAG): gen_normal('Q',f,t,inter)
    r0,c0=divmod(f,8)
    # knight
    for dr,dc in KN:
        r,c=r0+dr,c0+dc
        if onb(r,c): gen_normal('N',f,idx(r,c),[])
    # king (non-castle)
    for dr,dc in ADJ:
        r,c=r0+dr,c0+dc
        if onb(r,c): gen_normal('K',f,idx(r,c),[])

# pawns
for f in range(64):
    r,c=divmod(f,8)
    if not (1<=r<=6): continue
    # forward one
    tr=r-1
