                  68:('lit',epsq[0]), 69:('lit',epsq[1])}
            ed={f:'.', t:'P', capsq:'.', 68:'-',69:'-',70:'.'}
            add(cons,ed)

# castling
# kingside: e1=60 f1=61 g1=62 h1=63
cons={64:('lit','K'), 60:('lit','K'), 61:('lit','.'), 62:('lit','.'), 63:('lit','R')}
ed={60:'.',61:'R',62:'K',63:'.',64:'-',65:'-',68:'-',69:'-',70:'k'}
add(cons,ed)
# queenside: a1=56 b1=57 c1=58 d1=59 e1=60
cons={65:('lit','Q'), 60:('lit','K'), 59:('lit','.'), 58:('lit','.'), 57:('lit','.'), 56:('lit','R')}
ed={56:'.',58:'K',59:'R',60:'.',64:'-',65:'-',68:'-',69:'-',70:'q'}
add(cons,ed)

