def attack_frags(s):
    sr,sc=divmod(s,8)
    frags=[]
    for dr,dc in KN:
        r,c=sr+dr,sc+dc
        if onb(r,c): frags.append([(idx(r,c),'n')])
    for dr,dc in ADJ:
        r,c=sr+dr,sc+dc
        if onb(r,c): frags.append([(idx(r,c),'k')])
    for dc in (-1,1):
        r,c=sr-1,sc+dc
        if onb(r,c): frags.append([(idx(r,c),'p')])
    for dr,dc in ORTH:
        inter=[]; r,c=sr+dr,sc+dc
        while onb(r,c):
            m=idx(r,c)
            frags.append([(x,'\\.') for x in inter]+[(m,'[rq]')])
            inter.append(m); r+=dr; c+=dc
    for dr,dc in DIAG:
        inter=[]; r,c=sr+dr,sc+dc
        while onb(r,c):
            m=idx(r,c)
            frags.append([(x,'\\.') for x in inter]+[(m,'[bq]')])
            inter.append(m); r+=dr; c+=dc
    return frags

def lookahead(pairs):
    pairs=sorted(pairs)
    pos=0; body=''
    for i,a in pairs:
        g=i-pos
        if g>0: body+=('.{%d}'%g if g>1 else '.')
        body+=a; pos=i+1
    return '(?='+body+')'

# king safety
for s in range(64):
    for frag in attack_frags(s):
