R.append([r'X(.{8})(.{8})(.{8})(.{8})(.{8})(.{8})(.{8})(.{8})(.)(.)(.)(.)(..)(.)',
          r'\g<1>/\g<2>/\g<3>/\g<4>/\g<5>/\g<6>/\g<7>/\g<8> b \g<9>\g<10>\g<11>\g<12> \g<13> 0 0'])
